 sealed class SavedFrame {public byte[] Pixels;public int Width,Height;public string File;}
 static readonly List<SavedFrame> savedFrames=new List<SavedFrame>();
 static void SaveFrames(){foreach(var p in savedFrames){var bmp=BitmapSource.Create(p.Width,p.Height,96,96,PixelFormats.Pbgra32,null,p.Pixels,p.Width*4);using(var f=File.Create(p.File)){var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));png.Save(f);}}}
 static void Capture(Window w,string folder,int index,long elapsed,string label,Dictionary<string,object> frame){
  var rig=(ScaleTransform)G(w,"stretch");frame["elapsed_ms"]=elapsed;frame["row"]=P(G(w,"behavior"),"Animation");frame["playback_id"]=P(G(w,"behavior"),"PlaybackId");frame["scale_x"]=rig.ScaleX;frame["scale_y"]=rig.ScaleY;frame["body_width"]=G(w,"bodyWidth");
  // Two squash/rebound poses and later pet/drag poses are enough for visual
  // readback. Raw source pixels and the actual rig matrix are captured here.
  bool wanted=savedFrames.Count<1&&rig.ScaleY<.98||savedFrames.Count==1&&rig.ScaleY>1.008||savedFrames.Count==2&&elapsed>7100||savedFrames.Count==3&&elapsed>8200;
  var image=(Image)G(w,"image");var src=image.Source as BitmapSource;
  if(wanted&&src!=null){var bytes=new byte[src.PixelWidth*src.PixelHeight*4];src.CopyPixels(bytes,src.PixelWidth*4,0);string name="native-"+savedFrames.Count+".png";savedFrames.Add(new SavedFrame{Pixels=bytes,Width=src.PixelWidth,Height=src.PixelHeight,File=Path.Combine(folder,name)});frame["file"]=name;}
 }
